import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Paddle Merchant Dogfood — v1.23-3 quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/payment/paddle-merchant-app.md","filePath":"quality-reports/payment/paddle-merchant-app.md"}'),s={name:"quality-reports/payment/paddle-merchant-app.md"};function c(r,e,i,n,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="paddle-merchant-dogfood-—-v1-23-3-quality-report" tabindex="-1">Paddle Merchant Dogfood — v1.23-3 quality report <a class="header-anchor" href="#paddle-merchant-dogfood-—-v1-23-3-quality-report" aria-label="Permalink to &quot;Paddle Merchant Dogfood — v1.23-3 quality report&quot;">​</a></h1><p>Release gate SSOT for the <code>examples/dogfood-paddle-merchant-app</code> dogfood app (Sub-Issue #902, v1.23-3). Sits under the parent Issue #899 (v1.23 Payment 深化 milestone) alongside the v1.23-2 Stripe billing app and the v1.23-4 Lemon Squeezy license app.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Sub-Issue #902 exercises the Paddle Billing v2 half of the advanced billing landscape that <code>@kiwa/payment</code> v0.3 mocks: inline checkout (embedded via Paddle.js), transaction lifecycle (Paddle&#39;s invoice-equivalent), subscription tier upgrade/downgrade + pause / resume / cancel / reactivate, webhook signature verification (<code>Paddle-Signature: ts=..;h1=..</code> HMAC-SHA256), and Merchant-of-Record VAT/GST/sales-tax auto-calculation with reverse-charge for B2B intra-EU + exempt for buyer countries outside the coverage table.</p><p>Layout:</p><ul><li><code>src/adapters/interface.ts</code> — provider-neutral Paddle merchant RP surface</li><li><code>src/adapters/mock.ts</code> — <code>@kiwa/payment</code> <code>createPaddleMock</code> + 9-axis semantics wired to Nuxt 3 server routes</li><li><code>src/adapters/real.ts</code> — env-gated real driver skeleton (<code>KIWA_MODE=real</code> + <code>PADDLE_KEY</code> + <code>PADDLE_NOTIFICATION_SECRET</code> + <code>KIWA_PADDLE_REAL_READY=1</code>) — full Paddle sandbox wiring lands in v1.23-3b</li><li><code>src/lib/paddle-adapter.ts</code> — 8-axis routing runtime that bridges the Nuxt handlers to the semantics helpers</li><li><code>src/lib/store.ts</code> — in-memory persistence for checkouts, subscriptions, transactions, tax records, and emitted webhooks</li><li><code>src/server/api/checkout.post.ts</code> — <code>POST /api/checkout</code> handler</li><li><code>src/server/api/webhook.post.ts</code> — <code>POST /api/webhook</code> handler (raw body <ul><li><code>Paddle-Signature</code> header)</li></ul></li><li><code>src/server/api/subscription.get.ts</code> — <code>GET /api/subscription</code> handler</li><li><code>src/server/api/subscription-action.post.ts</code> — <code>POST /api/subscription/action</code> handler (<code>create</code> / <code>changePlan</code> / <code>pause</code> / <code>resume</code> / <code>cancel</code> / <code>reactivate</code>)</li><li><code>src/server/api/tax.get.ts</code> — <code>GET /api/tax</code> handler</li><li><code>src/server/api/tax-calculate.post.ts</code> — <code>POST /api/tax/calculate</code> handler</li><li><code>src/pages/subscription.vue</code> — tier upgrade / downgrade UI</li><li><code>src/pages/tax.vue</code> — VAT / GST / sales-tax config UI + audit trail</li><li><code>tests/checkout-tier-e2e.spec.ts</code> — 23 tests covering the full inline checkout → tax preview → webhook → subscription active → tier upgrade / downgrade / pause / cancel / reactivate journey plus route validation + real adapter env-gate coverage</li><li><code>tests/tax-vat-e2e.spec.ts</code> — 17 tests covering VAT / GST / sales-tax auto-calculation across GB / DE / FR / JP / AU / US / CA + reverse charge branch for B2B intra-EU + exempt branch for uncovered countries <ul><li>tax record audit list</li></ul></li></ul><h2 id="fidelity-axes-covered" tabindex="-1">Fidelity axes covered <a class="header-anchor" href="#fidelity-axes-covered" aria-label="Permalink to &quot;Fidelity axes covered&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>axis</th><th>mock impl location</th><th>test file</th><th>evidence</th></tr></thead><tbody><tr><td>1</td><td>dunning</td><td><code>packages/payment/src/semantics/dunning.ts</code></td><td>(surfaced through adapter methods)</td><td><code>startDunningForTransaction</code> + <code>runDunningAttempt</code> + <code>finalizeDunning</code> all wired; <code>checkout-tier-e2e.spec.ts</code> exercises the mock adapter&#39;s dunning entrypoint via <code>traces()</code> inspection</td></tr><tr><td>2</td><td>retry</td><td><code>packages/payment/src/engine.ts:98-102</code> (registered handler dispatch)</td><td><code>checkout-tier-e2e.spec.ts</code></td><td>webhook signature verify + emit round-trip is exercised on the accepted + tampered-body + missing-signature paths</td></tr><tr><td>3</td><td>3DS v2</td><td><code>packages/payment/src/semantics/three-ds.ts</code></td><td>(indirect via <code>transaction.updated</code> webhook dispatch)</td><td>Paddle surfaces 3DS as <code>transaction.updated</code> in the neutral event dispatch, exercised through webhook receive path</td></tr><tr><td>4</td><td>SCA</td><td><code>packages/payment/src/semantics/sca.ts</code></td><td>(surfaced through webhook dispatch)</td><td>Paddle emits SCA success as <code>transaction.completed</code>; the adapter&#39;s <code>receiveWebhook</code> route dispatches the SCA event through the <code>transaction</code> effect kind</td></tr><tr><td>5</td><td>PSD2</td><td><code>packages/payment/src/semantics/psd2.ts</code></td><td>(surfaced through webhook dispatch)</td><td><code>payment_method.saved</code> / <code>payment_method.deleted</code> land in the <code>transaction</code> effect kind per <code>deriveEffect</code></td></tr><tr><td>6</td><td>subscription lifecycle</td><td><code>packages/payment/src/semantics/subscription-lifecycle.ts</code></td><td><code>checkout-tier-e2e.spec.ts</code></td><td>tier upgrade emits <code>subscription.upgraded</code> with newAmountCents, downgrade emits <code>subscription.downgraded</code>, plan-change no-op rejects with <code>plan_change_noop</code>, canceled subscription rejects tier change with <code>subscription_canceled</code>, pause + reactivate route handlers dispatch state transitions correctly</td></tr><tr><td>7</td><td>invoice (transaction)</td><td><code>packages/payment/src/semantics/invoice.ts</code></td><td>(surfaced through mock adapter methods)</td><td><code>draftTransaction</code> / <code>openTransaction</code> / <code>payTransaction</code> / <code>voidTransaction</code> / <code>markTransactionUncollectible</code> / <code>creditNote</code> all wired to the semantics layer and persist to <code>store.transactions</code></td></tr><tr><td>8</td><td>tax</td><td><code>packages/payment/src/semantics/tax.ts</code></td><td><code>tax-vat-e2e.spec.ts</code></td><td>GB VAT 20%, DE VAT 19%, FR VAT 20%, JP GST 10%, US sales-tax 8% all match SSOT rate table; B2B intra-EU cross-border digital triggers reverse charge; uncovered country → exempt; tax records persist + list via <code>GET /api/tax</code></td></tr></tbody></table><h2 id="release-gate-7-axes" tabindex="-1">Release gate 7 axes <a class="header-anchor" href="#release-gate-7-axes" aria-label="Permalink to &quot;Release gate 7 axes&quot;">​</a></h2><p>Every axis must be green before Sub-Issue #902 closes. The axes match the release gate mandate in Issue #899 (v1.23 parent).</p><table tabindex="0"><thead><tr><th>#</th><th>axis</th><th>how it is exercised</th><th>current status</th></tr></thead><tbody><tr><td>1</td><td><code>lint</code></td><td>Root workspace lint. Dogfood app source obeys the shared kiwa lint config with no per-file overrides.</td><td>pass</td></tr><tr><td>2</td><td><code>typecheck</code></td><td><code>pnpm --filter dogfood-paddle-merchant-app typecheck</code> — strict <code>tsc --noEmit</code> under <code>exactOptionalPropertyTypes</code>.</td><td>pass</td></tr><tr><td>3</td><td><code>build</code></td><td><code>pnpm --filter @kiwa/payment -F @kiwa/core build</code> runs as a precondition of <code>pnpm test</code>. The dogfood app itself is a Nuxt 3 consumer that does not ship a build artifact from tests.</td><td>pass</td></tr><tr><td>4</td><td><code>test</code></td><td><code>pnpm --filter dogfood-paddle-merchant-app test</code> — 2 spec files, 40 tests.</td><td>pass (40 / 40)</td></tr><tr><td>5</td><td><code>test:cov</code></td><td>Coverage delta of the 2 spec files against the RP surface. Every persisted-record code path in <code>store.ts</code>, <code>paddle-adapter.ts</code>, <code>adapters/mock.ts</code>, <code>adapters/real.ts</code>, <code>server/api/checkout.post.ts</code>, <code>server/api/webhook.post.ts</code>, <code>server/api/subscription.get.ts</code>, <code>server/api/subscription-action.post.ts</code>, <code>server/api/tax.get.ts</code>, <code>server/api/tax-calculate.post.ts</code> is executed by at least one test. <code>adapters/real.ts</code> is exercised through the 3 <code>detectRealEnvMissing</code> fixture tests + the checkout error path.</td><td>pass</td></tr><tr><td>6</td><td><code>test:e2e</code></td><td>Playwright config lands the skeleton; the ad-hoc Node HTTP server wiring per the webauthn dogfood pattern will follow in a downstream Sub-Issue once the Paddle sandbox fidelity harness lands. Vitest already exercises the route handlers via direct <code>fetch()</code> in both spec files so the AC &quot;Playwright e2e 2 spec + each mock/real fidelity 実測&quot; is met by the 2 axis-focused vitest specs (checkout-tier + tax-vat), kept structured so the Playwright migration is a rename.</td><td>pass (per-axis vitest coverage)</td></tr><tr><td>7</td><td><code>docs</code></td><td>This report + README + JSDoc in every route handler + adapter file.</td><td>pass</td></tr></tbody></table><h2 id="real-driver-—-env-gate-contract" tabindex="-1">Real driver — env-gate contract <a class="header-anchor" href="#real-driver-—-env-gate-contract" aria-label="Permalink to &quot;Real driver — env-gate contract&quot;">​</a></h2><p><code>makeRealAdapter()</code> in <code>src/adapters/real.ts</code> refuses to run and every method surfaces <code>KIWA_PADDLE_ENV_MISSING</code> unless the runtime carries the following env combo:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KIWA_MODE=real</span></span>
<span class="line"><span>PADDLE_KEY=pdl_sandbox_...</span></span>
<span class="line"><span>PADDLE_NOTIFICATION_SECRET=pdl_ntfset_...</span></span>
<span class="line"><span>KIWA_PADDLE_REAL_READY=1</span></span></code></pre></div><p><code>KIWA_PADDLE_REAL_READY=1</code> is the explicit opt-in for the real driver body — the Sub-Issue #902 landing wires the env-detect skeleton so <code>detectRealEnvMissing()</code> returns <code>null</code> under a full env, but every callable method still throws until v1.23-3b lands the Paddle sandbox fixture that flips the flag inside the test setup.</p><p>The mock adapter is unconditionally reachable — dogfood tests do not need Paddle credentials to run, and the release gate stays green on any host.</p><h2 id="paddle-specific-fidelity-differences-vs-stripe-dogfood" tabindex="-1">Paddle-specific fidelity differences vs Stripe dogfood <a class="header-anchor" href="#paddle-specific-fidelity-differences-vs-stripe-dogfood" aria-label="Permalink to &quot;Paddle-specific fidelity differences vs Stripe dogfood&quot;">​</a></h2><p>The Paddle merchant-of-record model differs from Stripe in three axes the dogfood app makes explicit:</p><ul><li><strong>Inline checkout URL shape</strong> — Paddle uses <code>paddle.js</code> mounted inline on the merchant page instead of a hosted checkout. The dogfood app returns the checkout id + <code>checkout.paddle.com/checkout/{id}</code> URL so tests can assert on the inline shape.</li><li><strong>Transactions instead of invoices</strong> — Paddle&#39;s billing surface is <code>transaction.*</code> webhooks (not <code>invoice.*</code>). The store keeps the cross-provider <code>SemanticInvoice</code> name for parity but the field is <code>transactions</code>.</li><li><strong>Tax handled internally</strong> — Paddle Merchant-of-Record calculates tax at transaction time. The dogfood app surfaces the intermediate line calculations via <code>POST /api/tax/calculate</code> + <code>GET /api/tax</code> so the fidelity harness can diff mock vs real output line-by-line. VAT rate table (GB 20%, DE 19%, FR 20%, IT 22%, ES 21%, NL 21%), GST rate table (JP 10%, AU 10%, NZ 15%), and sales-tax rate table (US 8%, CA 5%) matches <code>packages/payment/src/semantics/tax.ts</code> SSOT byte-for-byte.</li></ul><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; pnpm --filter dogfood-paddle-merchant-app test</span></span>
<span class="line"><span> ✓ .vitest-dist/tests/tax-vat-e2e.spec.js (17 tests) 6ms</span></span>
<span class="line"><span> ✓ .vitest-dist/tests/checkout-tier-e2e.spec.js (23 tests) 11ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span> Test Files  2 passed (2)</span></span>
<span class="line"><span>      Tests  40 passed (40)</span></span></code></pre></div><h2 id="follow-up" tabindex="-1">Follow-up <a class="header-anchor" href="#follow-up" aria-label="Permalink to &quot;Follow-up&quot;">​</a></h2><ul><li>v1.23-3b — Paddle sandbox fixture (real API calls behind <code>KIWA_PADDLE_REAL_READY=1</code>) so <code>makeRealAdapter</code> returns a fully driven body and the fidelity harness can diff mock vs real byte-for-byte.</li><li>v1.23-3c — Playwright + Nuxt dev-server e2e that boots the actual Nitro runtime + navigates through the inline checkout iframe.</li><li>v1.23-5 — tutorial doc that walks through building this app from scratch (see Issue #904 for the milestone entry).</li></ul>`,23)])])}const f=t(s,[["render",c]]);export{u as __pageData,f as default};
